-- DMD Producción: base exclusiva, sin datos reales precargados.
create extension if not exists pgcrypto;
create table if not exists production_clients (id uuid primary key default gen_random_uuid(), name text not null unique, credit_days integer default 21 check (credit_days>=0), credit_day_type text default 'calendar' check (credit_day_type in ('calendar','business')), created_at timestamptz default now());
create table if not exists production_services (id uuid primary key default gen_random_uuid(), client_id uuid not null references production_clients(id), internal_code text not null, service_order_number text, site text, address text, service_type text not null, received_at date not null default current_date, reception_channel text, contact_name text, owner text, current_stage smallint not null default 1 check (current_stage between 1 and 10), status text not null default 'request_received', budget_ex_vat numeric(14,2), budget_vat numeric(14,2), approved_ex_vat numeric(14,2), estimated_cost numeric(14,2), actual_cost numeric(14,2), invoice_number text, invoice_date date, invoice_received_at date, credit_start_event text, due_date date, invoiced_amount numeric(14,2), currency text default 'PEN', collection_status text default 'pending_invoice', notes text, created_at timestamptz default now(), updated_at timestamptz default now(), unique(client_id,internal_code));
create table if not exists production_stage_events (id uuid primary key default gen_random_uuid(), service_id uuid not null references production_services(id) on delete cascade, stage smallint not null check (stage between 1 and 10), occurred_at timestamptz, responsible text, notes text, exception_reason text, created_at timestamptz default now());
create table if not exists production_costs (id uuid primary key default gen_random_uuid(), service_id uuid not null references production_services(id) on delete cascade, category text not null check(category in ('labor','materials','transport','equipment','supervision','other')), estimated numeric(14,2), actual numeric(14,2), notes text, created_at timestamptz default now());
create table if not exists production_payments (id uuid primary key default gen_random_uuid(), service_id uuid not null references production_services(id) on delete cascade, paid_at date not null, amount numeric(14,2) not null check(amount>0), evidence_url text, notes text, created_at timestamptz default now());
create table if not exists production_documents (id uuid primary key default gen_random_uuid(), service_id uuid not null references production_services(id) on delete cascade, stage smallint check(stage between 1 and 10), document_type text not null, file_name text not null, storage_path text not null, created_at timestamptz default now());
create index if not exists production_services_client_stage on production_services(client_id,current_stage);
create index if not exists production_stage_events_service on production_stage_events(service_id,stage);
